import { total } from './total.js';

test('sums finite numbers', () => {
  expect(total([2, 3])).toBe(5);
  expect(total([-2, -3])).toBe(-5);
  expect(total([])).toBe(0);
});

test('rejects non-numeric and nonfinite entries', () => {
  expect(() => total(['invalid'])).toThrow('Non-numeric or nonfinite entry');
  expect(() => total([NaN])).toThrow('Non-numeric or nonfinite entry');
  expect(() => total([Infinity])).toThrow('Non-numeric or nonfinite entry');
});

